from pathlib import Path
p=Path('NAYAHUB.html')
s=p.read_text(encoding='utf-8')
if 'NAYANET-V7-REMAINING-TODO-COMPLETION' in s: raise SystemExit(0)
layer=r'''<script id="NAYANET-V7-REMAINING-TODO-COMPLETION">
(()=>{'use strict';
const K='nayanet_hub_intelligence_v3';const load=()=>{try{return JSON.parse(localStorage.getItem(K))||{fav:{},save:{},lists:[],eng:{},feedback:[]}}catch{return{fav:{},save:{},lists:[],eng:{},feedback:[]}}};const st=load(),put=()=>{try{localStorage.setItem(K,JSON.stringify(st))}catch{}};const esc=x=>String(x??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\':'&#92;','"':'&quot;'}[c]||c));
const notes=()=>{try{return JSON.parse(localStorage.getItem('nayanet_v7_live_notes')||'[]')}catch{return[]}};const blocks=()=>notes().map(n=>{let t=String(n.text||'').trim(),title=(t.split(/[.!?]\s+/)[0]||'Intelligent Event').replace(/^#+\s*/,'').slice(0,110);return{id:'ib-'+n.id,title,summary:t,human:t,naya:'Naya interpretation is pending the connected production intelligence service.',machine:'event_id '+n.id+' · '+(n.type||'INSIGHT')+' · '+n.createdAt+' · local_persisted · private',type:n.type||'INSIGHT',tags:[n.type||'INSIGHT','SMART NOTE'],createdAt:n.createdAt,collective:false}});
const nutshell=t=>{t=String(t||'').replace(/\s+/g,' ').trim();if(t.length<=240)return t;let x=t.slice(0,260),i=Math.max(x.lastIndexOf('. '),x.lastIndexOf(' '));return x.slice(0,i>120?i:240).replace(/[.,;:!?-]+$/,'')+'.'};
function css(){if(document.getElementById('nh-final-css'))return;let s=document.createElement('style');s.id='nh-final-css';s.textContent=`#nhFinalSearch{margin:12px 0 20px;position:relative}#nhFinalSearch input{width:100%;min-height:62px;padding:0 145px 0 20px;border:2px solid #8b63ff88;border-radius:18px;background:#0b0a10;color:#fff;font-size:15px;outline:0;box-shadow:0 18px 40px #000b}#nhFinalSearch input:focus{border-color:#d86cff}#nhTalk{position:absolute;right:8px;top:8px;height:46px;border:1px solid #d86cff88;border-radius:12px;background:#21102c;color:#fff;padding:0 13px;font-size:8px;font-weight:1000}.nhf-results{display:none;position:absolute;z-index:500;left:0;right:0;top:70px;padding:8px;border:1px solid #d86cff55;border-radius:16px;background:#08080ef7}.nhf-results.open{display:grid;gap:5px}.nhf-result{padding:12px;border:1px solid transparent;border-radius:10px;background:transparent;color:#fff;text-align:left}.nhf-result:hover{border-color:#d86cff55;background:#ffffff08}.nhf-result b{display:block}.nhf-result small{display:block;color:#aaa4b1;margin-top:4px}.nhf-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:14px;padding-top:12px;border-top:1px solid #ffffff12}.nhf-actions button{min-height:34px;padding:0 10px;border:1px solid #ffffff22;border-radius:9px;background:#08080c;color:#ddd8e3;font-size:7px;font-weight:1000}.nhf-on{border-color:#55e39a!important;color:#bfffd8!important}.nhf-card{padding:18px;margin:0 0 11px;border:1px solid #ffffff1d;border-radius:19px;background:linear-gradient(145deg,#14141a,#09090d);box-shadow:inset 0 1px #fff3,0 18px 38px #0009}.nhf-card h3{font-size:18px;margin:5px 0}.nhf-nutshell{padding:12px;margin:12px 0;background:#0a090e;border-left:2px solid #d86cff;color:#eee9f1;font-size:11px;line-height:1.6}.nhf-persp{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.nhf-persp div{padding:11px;border:1px solid #ffffff14;border-radius:11px;background:#08080c}.nhf-persp b{display:block;font-size:6px;letter-spacing:.13em;margin-bottom:5px}.nhf-persp span{font-size:8px;line-height:1.5;color:#aaa4b1}.nhf-modal{position:fixed;inset:0;z-index:1200;display:grid;place-items:center;padding:18px;background:#000c;backdrop-filter:blur(18px)}.nhf-dialog{width:min(900px,100%);max-height:92vh;overflow:auto;padding:22px;border:1px solid #d86cff66;border-radius:24px;background:#0d0b12;box-shadow:0 40px 100px #000f}.nhf-dialog textarea,.nhf-dialog input,.nhf-dialog select{width:100%;padding:12px;background:#07070a;color:#fff;border:1px solid #ffffff22;border-radius:12px}.nhf-dialog textarea{min-height:150px}.nhf-share{display:grid;grid-template-columns:1.05fr .95fr;gap:15px}.nhf-card-preview{min-height:330px;padding:24px;border:1px solid #d86cff66;border-radius:20px;background:radial-gradient(450px 260px at 75% 20%,#d86cff24,transparent 60%),#050507;display:flex;flex-direction:column;justify-content:space-between}.nhf-card-preview .hook{font-size:28px;font-weight:900;line-height:1.05}.nhf-card-preview .cta{align-self:flex-end;padding:9px 12px;border:1px solid #d86cffaa;border-radius:10px;font-size:8px;font-weight:1000}.nhf-list-page{display:grid;grid-template-columns:240px 1fr;gap:15px}.nhf-list{padding:13px;border:1px solid #ffffff18;border-radius:14px;background:#09090d;margin-bottom:7px;cursor:pointer}.nhf-list.active{border-color:#d86cff;background:#1b1024}.nhf-list b{font-size:9px}.nhf-list span{display:block;color:#88828f;font-size:7px;margin-top:4px}@media(max-width:760px){.nhf-persp,.nhf-share,.nhf-list-page{grid-template-columns:1fr}#nhFinalSearch input{padding-right:110px}.nhf-dialog{padding:15px}}`;document.head.appendChild(s)}
function modal(html){let m=document.createElement('div');m.className='nhf-modal';m.innerHTML=html;document.body.appendChild(m);m.onclick=e=>{if(e.target===m)m.remove()};return m}
function updateHome(){let p=document.getElementById('page-home');if(!p)return;let h=p.querySelector('.heroIntro h1'),sub=p.querySelector('.heroIntro p');if(h)h.textContent='YOUR INTELLIGENCE TODAY';if(sub)sub.textContent='What happened · What matters · What you learned · What Naya recommends · What you can do next';let hc=p.querySelector('.heroCopy h2'),hp=p.querySelector('.heroCopy p');if(hc)hc.textContent='Your life creates intelligence every day. Naya helps you capture it, understand it, remember it, compound it, and use it.';if(hp)hp.textContent='Naya does not make you consume more AI. Naya makes useful intelligence easier for humans to consume.';let ft=p.querySelector('.intelligentFeedHead h2');if(ft)ft.textContent='What should I know today?';let fp=p.querySelector('.intelligentFeedHead p');if(fp)fp.textContent='A living compression of what happened, what matters, what you learned, and what to do next.'}
function search(){if(document.getElementById('nhFinalSearch'))return;let top=document.querySelector('.topbar');if(!top)return;let bar=document.createElement('div');bar.id='nhFinalSearch';bar.innerHTML='<input placeholder="TYPE OR TALK TO NAYA — find your intelligence…"><button id="nhTalk">🎙 TALK TO NAYA</button><div class="nhf-results"></div>';top.insertAdjacentElement('afterend',bar);let i=bar.querySelector('input'),r=bar.querySelector('.nhf-results'),run=()=>{let q=i.value.trim().toLowerCase();if(!q){r.classList.remove('open');return}let a=blocks().filter(b=>(b.title+' '+b.summary+' '+b.type+' '+b.tags.join(' ')).toLowerCase().includes(q)).slice(0,8);r.innerHTML=a.length?a.map(b=>'<button class="nhf-result"><b>'+esc(b.title)+'</b><small>'+esc(nutshell(b.summary))+'</small></button>').join(''):'<div class="nhf-result"><b>No matching intelligence yet.</b><small>Search your preserved Smart Notes and Intelligent Blocks.</small></div>';r.classList.add('open')};i.oninput=run;i.onkeydown=e=>{if(e.key==='Escape')r.classList.remove('open');if(e.key==='Enter')run()};bar.querySelector('#nhTalk').onclick=()=>{let SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){i.focus();return}let x=new SR();x.lang=navigator.language||'en-CA';x.onstart=()=>bar.querySelector('#nhTalk').textContent='🎙 LISTENING…';x.onresult=e=>{i.value=e.results[0][0].transcript;run()};x.onend=()=>bar.querySelector('#nhTalk').textContent='🎙 TALK TO NAYA';x.onerror=x.onend;x.start()}}
function card(b){let fav=!!st.fav[b.id],sav=!!st.save[b.id],e=st.eng[b.id]||{},likes=e.likes||0,love=!!e.love,rate=e.rate||0,comments=(e.comments||[]).length;return '<article class="nhf-card"><div class="eyebrow">'+esc(b.type)+' · PERSONAL</div><h3>'+esc(b.title)+'</h3><div class="nhf-nutshell"><b style="font-size:7px;letter-spacing:.12em;color:#b99aff">NUTSHELL · 40-WORD PRINCIPLE</b><br>'+esc(nutshell(b.summary))+'</div><div class="nhf-persp"><div><b>HUMAN</b><span>'+esc(nutshell(b.human))+'</span></div><div><b>NAYA</b><span>'+esc(nutshell(b.naya))+'</span></div><div><b>MACHINE</b><span>'+esc(nutshell(b.machine))+'</span></div></div><div class="nhf-actions"><button data-fav="'+esc(b.id)+'" class="'+(fav?'nhf-on':'')+'">★ '+(fav?'FAVORITED':'FAVORITE')+'</button><button data-save="'+esc(b.id)+'" class="'+(sav?'nhf-on':'')+'">🔖 '+(sav?'SAVED':'SAVE')+'</button><button data-like="'+esc(b.id)+'">👍 LIKE '+likes+'</button><button data-love="'+esc(b.id)+'" class="'+(love?'nhf-on':'')+'">♥ '+(love?'LOVED':'LOVE')+'</button><button data-rank="'+esc(b.id)+'">★ RANK '+(rate?rate+'/5':'')+'</button><button data-comment="'+esc(b.id)+'">💬 COMMENT '+(comments||'')+'</button><button data-share="'+esc(b.id)+'">＋ SHARE</button><button data-list="'+esc(b.id)+'">＋ LIST</button></div></article>'}
function addHomeFeed(){let p=document.getElementById('page-home');if(!p||document.getElementById('nhFinalBlocks'))return;let s=document.createElement('section');s.id='nhFinalBlocks';s.innerHTML='<div style="margin:22px 0 10px"><div class="eyebrow">INTELLIGENT BLOCKS</div><h2 style="font-size:25px;margin:6px 0">CREATE · UNDERSTAND · COMPOUND · USE · SHARE</h2><p style="color:#aaa4b1;font-size:10px">One event. Human · Naya · Machine · Nutshell · Evidence · Smart Link.</p></div><div id="nhFinalBlockList"></div><div class="nhf-card"><b style="font-size:9px;letter-spacing:.12em">PRIVACY</b><p style="color:#c8c2cd;font-size:10px;line-height:1.6">PRIVATE BY DEFAULT · SHARED BY CHOICE · COLLECTIVE BY CONSENT · PUBLIC BY DECISION</p></div>';p.appendChild(s);renderHomeBlocks()}
function renderHomeBlocks(){let root=document.getElementById('nhFinalBlockList');if(root)root.innerHTML=blocks().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,8).map(card).join('')||'<div class="nhf-card"><b>No preserved events yet.</b><p>Create a Smart Note to begin.</p></div>'}
function lists(){if(document.getElementById('page-nh-lists'))return;let p=document.createElement('section');p.className='page';p.id='page-nh-lists';p.innerHTML='<div class="pageHead"><div><div class="eyebrow">YOUR INTELLIGENCE ORGANIZED</div><h1>Naya Lists</h1><p>Smart Lists for your intelligence. One Intelligent Block may belong to multiple lists.</p></div><button class="btn purple" id="nhNewList">+ NEW LIST</button></div><div class="nhf-list-page"><div id="nhListNav"></div><div id="nhListBody"></div></div>';document.querySelector('.main')?.appendChild(p);p.querySelector('#nhNewList').onclick=()=>{let n=prompt('Name your Naya List');if(!n?.trim())return;st.lists.push({id:'l-'+Date.now(),name:n.trim(),items:[]});put();renderLists()};renderLists()}
function renderLists(active){let nav=document.getElementById('nhListNav'),body=document.getElementById('nhListBody');if(!nav||!body)return;if(!st.lists.length){nav.innerHTML='<div class="nhf-list active"><b>No lists yet</b><span>Create your first Smart List.</span></div>';body.innerHTML='<div class="nhf-card"><h3>Naya Lists</h3><p>Ideas for My Business · Things I Need to Remember · Breakthroughs · Research · My Best Lessons · Future Opportunities</p></div>';return}active=active||st.lists[0].id;nav.innerHTML=st.lists.map(l=>'<div class="nhf-list '+(l.id===active?'active':'')+'" data-l="'+l.id+'"><b>'+esc(l.name)+'</b><span>'+l.items.length+' Intelligent Blocks</span></div>').join('');let l=st.lists.find(x=>x.id===active),bs=blocks().filter(b=>l.items.includes(b.id));body.innerHTML='<div class="nhf-card"><h3>'+esc(l.name)+'</h3>'+(bs.length?bs.map(card).join(''):'<p>No blocks in this list yet. Use + LIST on an Intelligent Block.</p>')+'</div>';nav.querySelectorAll('[data-l]').forEach(x=>x.onclick=()=>renderLists(x.dataset.l))}
function share(id){let b=blocks().find(x=>x.id===id);if(!b)return;let m=modal('<div class="nhf-dialog"><h2>SHARE INTELLIGENCE</h2><p style="color:#aaa4b1;font-size:10px">Your social post appears first. The standardized NayaNET Intelligent Share Card appears next. Keep your complete Ambassador URL intact.</p><div class="nhf-share"><div class="nhf-card-preview"><div style="font-size:9px;font-weight:1000;letter-spacing:.15em">NayaNET · INTELLIGENT BLOCK</div><div><div class="hook">'+esc(b.title)+'</div><p style="color:#c7c0ce;font-size:11px;line-height:1.5">'+esc(nutshell(b.summary))+'</p></div><div><div style="font-size:9px;letter-spacing:.1em">CREATE. CONNECT. GROW WITH US.</div><div class="cta">ENTER NayaNET</div></div></div><div><label style="font-size:8px;font-weight:1000">YOUR SOCIAL POST</label><textarea id="nhPost">'+esc(nutshell(b.summary))+'</textarea><label style="display:block;margin-top:9px;font-size:8px;font-weight:1000">DESTINATION / AMBASSADOR URL</label><input id="nhRef" value="'+esc(localStorage.getItem('nayanet_ambassador_url')||'https://NayaNET.xyz/')+'"><div class="nhf-actions"><button id="nhCopy">COPY LINK</button><button id="nhNative">SHARE</button><button id="nhFb">FACEBOOK</button><button id="nhLi">LINKEDIN</button><button id="nhClose">CLOSE</button></div></div></div></div>');let url=m.querySelector('#nhRef').value||location.href;m.querySelector('#nhClose').onclick=()=>m.remove();m.querySelector('#nhCopy').onclick=()=>navigator.clipboard?.writeText(url);m.querySelector('#nhNative').onclick=()=>navigator.share?navigator.share({title:b.title,text:m.querySelector('#nhPost').value,url}):navigator.clipboard?.writeText(url);m.querySelector('#nhFb').onclick=()=>window.open('https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(url),'_blank','noopener');m.querySelector('#nhLi').onclick=()=>window.open('https://www.linkedin.com/sharing/share-offsite/?url='+encodeURIComponent(url),'_blank','noopener')}
function rank(id){let m=modal('<div class="nhf-dialog"><h2>★ HOW VALUABLE IS THIS INTELLIGENCE?</h2><div id="nhStars" class="nhf-actions"></div><button class="btn" id="nhCancel">CANCEL</button></div>');for(let i=1;i<=5;i++){let x=document.createElement('button');x.textContent='★'.repeat(i);x.onclick=()=>{(st.eng[id]||(st.eng[id]={})).rate=i;put();m.remove();renderHomeBlocks()};m.querySelector('#nhStars').appendChild(x)}m.querySelector('#nhCancel').onclick=()=>m.remove()}
function comment(id){let m=modal('<div class="nhf-dialog"><h2>💬 COMMENT ON THIS INTELLIGENCE</h2><textarea id="nhComment" placeholder="Write your comment…"></textarea><div class="nhf-actions"><button id="nhPost">POST COMMENT</button><button id="nhClose">CANCEL</button></div></div>');m.querySelector('#nhClose').onclick=()=>m.remove();m.querySelector('#nhPost').onclick=()=>{let t=m.querySelector('#nhComment').value.trim();if(!t)return;(st.eng[id]||(st.eng[id]={})).comments=((st.eng[id]?.comments)||[]).concat({text:t,at:new Date().toISOString()});put();m.remove();renderHomeBlocks()}}
function feedback(){let m=modal('<div class="nhf-dialog"><h2>💡 HELP US MAKE NayaNET BETTER</h2><select id="nhFbType"><option>Idea</option><option>Suggestion</option><option>Bug</option><option>Feature Request</option><option>Experience</option><option>Other</option></select><textarea id="nhFb" style="margin-top:8px" placeholder="Tell us what would make NayaNET better…"></textarea><div class="nhf-actions"><button id="nhFbSend">SUBMIT</button><button id="nhFbClose">DONE</button></div></div>');m.querySelector('#nhFbClose').onclick=()=>m.remove();m.querySelector('#nhFbSend').onclick=()=>{st.feedback.push({type:m.querySelector('#nhFbType').value,text:m.querySelector('#nhFb').value,at:new Date().toISOString()});put();m.remove()}}
function ask(){let m=modal('<div class="nhf-dialog"><h2>ASK NAYA</h2><p style="color:#aaa4b1;font-size:10px">Search finds existing intelligence. Ask Naya is reserved for conversational Superbrain reasoning when that service is connected.</p><div id="nhAskOut" class="nhf-card">No remote reasoning endpoint is connected in this static package. Naya will not fabricate an answer.</div><input id="nhAskIn" placeholder="Ask Naya anything…"><div class="nhf-actions"><button id="nhAskGo">ASK</button><button id="nhAskClose">DONE</button></div></div>');m.querySelector('#nhAskClose').onclick=()=>m.remove();m.querySelector('#nhAskGo').onclick=()=>{let q=m.querySelector('#nhAskIn').value.toLowerCase(),h=blocks().find(b=>(b.title+' '+b.summary+' '+b.type).toLowerCase().includes(q));m.querySelector('#nhAskOut').textContent=h?'Existing intelligence found: '+nutshell(h.summary):'No matching preserved intelligence. Connect the production Superbrain endpoint for conversational reasoning.'}}
function wire(){document.addEventListener('click',e=>{let x=e.target.closest('[data-fav]');if(x){st.fav[x.dataset.fav]=!st.fav[x.dataset.fav];put();renderHomeBlocks()}let y=e.target.closest('[data-save]');if(y){st.save[y.dataset.save]=!st.save[y.dataset.save];put();renderHomeBlocks()}let l=e.target.closest('[data-like]');if(l){let z=st.eng[l.dataset.like]||(st.eng[l.dataset.like]={});z.likes=(z.likes||0)+(z.liked?-1:1);z.liked=!z.liked;put();renderHomeBlocks()}let v=e.target.closest('[data-love]');if(v){let z=st.eng[v.dataset.love]||(st.eng[v.dataset.love]={});z.love=!z.love;put();renderHomeBlocks()}let r=e.target.closest('[data-rank]');if(r)rank(r.dataset.rank);let c=e.target.closest('[data-comment]');if(c)comment(c.dataset.comment);let sh=e.target.closest('[data-share]');if(sh)share(sh.dataset.share);let li=e.target.closest('[data-list]');if(li){if(!st.lists.length){lists();alert('Create a Naya List first.');return}let n=prompt(st.lists.map((q,i)=>(i+1)+'. '+q.name).join('\n')+'\n\nEnter list number:');let q=st.lists[parseInt(n,10)-1];if(q&&!q.items.includes(li.dataset.list))q.items.push(li.dataset.list);put();renderLists(q?.id)}})}
function nav(){let n=document.querySelector('.sidebar .nav');if(n&&!document.getElementById('nhListsNav')){let b=document.createElement('button');b.id='nhListsNav';b.innerHTML='<span class="ico">▤</span>Naya Lists';n.appendChild(b);b.onclick=e=>{e.preventDefault();document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.getElementById('page-nh-lists').classList.add('active');let t=document.getElementById('pageTitle');if(t)t.textContent='Naya Lists';renderLists()}}}
function util(){if(document.getElementById('nhFinalUtil'))return;let d=document.createElement('div');d.id='nhFinalUtil';d.style='position:fixed;right:18px;bottom:78px;z-index:80;display:flex;gap:7px';d.innerHTML='<button class="btn small" id="nhFeedback">💡 GIVE FEEDBACK</button><button class="btn small purple" id="nhAsk">ASK NAYA</button>';document.body.appendChild(d);d.querySelector('#nhFeedback').onclick=feedback;d.querySelector('#nhAsk').onclick=ask}
function init(){css();updateHome();search();addHomeFeed();lists();nav();util();wire()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();</script>
'''
if '</body>' not in s: raise SystemExit('No body marker')
s=s.replace('</body>',layer+'</body>',1)
p.write_text(s,encoding='utf-8')
